function load(){
  if(loaded) return; loaded=true;
  var f=document.createElement('iframe');
  f.src='https://cal.com/anthonytoday/consultation?embed=1';
  f.title='Réserver une consultation';
  f.loading='lazy';
  f.setAttribute('style','width:100%;height:860px;min-height:860px;border:none;border-radius:8px;');
  b.replaceWith(f);
}
b.addEventListener('click', load);
// Warm it up on intent, so the click feels instant without costing anything on load.
b.addEventListener('mouseenter', function(){
  if(loaded||document.getElementById('cal-pre')) return;
  var l=document.createElement('link');
  l.id='cal-pre'; l.rel='preconnect'; l.href='https://cal.com';
  document.head.appendChild(l);
});
